# The bundle's host shim (generated by world/gen_hier.py bundle): the world's alf_host (world/ above the package,
# metis.host.world_host) once a game.json is beside it (an install's), else metispy's PassHost: no world, the program alone.
import os

HERE = os.path.dirname(os.path.abspath(__file__))


def make(case=None):
    import metis.host as h                 # PassHost: metispy 0.2.1
    if not os.path.exists(os.path.join(HERE, "game.json")):
        return h.PassHost()
    return h.world_host(HERE, "alf_host", env="METIS_ALF_WORLD").AlfHost(HERE, case)
